import{d as c,C as t,o as u,c as b,j as a,a as r,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十章","description":"以烹小鲜读不扰，以鬼神与圣人两不伤人读德交归，保留古代鬼神语境。","frontmatter":{"title":"道德经第六十章","description":"以烹小鲜读不扰，以鬼神与圣人两不伤人读德交归，保留古代鬼神语境。","category":"guide","aliases":["道德经第六十章","老子第六十章","dao de jing chapter 60"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-60.md","filePath":"daoism/dao-de-jing/chapter-60.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-60.md"},y=c({...g,setup(p){const n=[{id:"cooking-small-fish",label:"治大国若烹小鲜",showLabel:!0,sentences:[["治大国若烹小",{text:"鲜",glossary:"xian"},"。"]],note:["【白话】治理大国，如同烹煮小鱼，要避免躁扰而损伤所照料的对象。以小鲜为喻，是先说明治理用力的方式。","【王弼注择要】「不扰也。」又说「躁则多害，静则全真」，并将国愈大与其主愈静相连。","【读法】鲜为小鱼。烹小鲜常可借少翻搅说明，但所据注直接说的是不扰；本页不把具体烹饪步骤充作古注原话。静也包含审慎照料，而不只是停止履责。"]},{id:"approaching-through-dao",label:"以道莅天下，其鬼不神",showLabel:!0,sentences:[["以道",{text:"莅",glossary:"li"},"天下，其",{text:"鬼",glossary:"gui"},"不",{text:"神",glossary:"shenverb"},"；"]],note:["【白话】以道临治天下，鬼灵便不显出使人惊惧、受害的神异作用。下一句继续解释这种不神，不宜脱离后文单独判断。","【王弼注择要】「治大国则若烹小鲜，以道莅天下则其鬼不神也。」王弼把前句的不扰接到本句的以道临治。","【读法】莅为临治；神在不神中作显神异之用。鬼神是古代文本实际使用的观念，本页保留其语境，不据此作现实存在与效力的实证结论。"]},{id:"spiritual-power-without-harming",label:"非其鬼不神，其神不伤人",showLabel:!0,sentences:[["非其",{text:"鬼",glossary:"gui"},"不",{text:"神",glossary:"shenverb"},"，其",{text:"神",glossary:"shen"},"不伤人；"]],note:["【白话】并不是说鬼灵没有神异之能，而是说这种神异不伤害人。前句的不神，由这里转为不伤人来说明。","【王弼注择要】「物守自然，则神无所加。」又说「神无所加，则不知神之为神也」，从不害自然、无从加害说明何以不显其神。","【读法】这里的神连鬼神之能理解，与上一句动词用法分列。古注关心的是自然得到保全、神力不加为害，不把消灾驱鬼的方法写进经文。"]},{id:"the-sage-also-without-harming",label:"圣人亦不伤人",showLabel:!0,sentences:[["非其",{text:"神",glossary:"shen"},"不伤人，",{text:"圣人",glossary:"shengren"},"亦不伤人。"]],note:["【白话】不只是鬼神之能不伤害人，圣人也不伤害人。这个非其……亦……的递进，把所求从鬼神之不害推进到治理者自身不害。","【王弼注择要】「道洽则圣人亦不伤人。」注又批评「恃威网以使物者，治之衰也」，并说「不知圣人之为圣也」，强调治理不靠威势显圣。","【读法】圣人是本章理想的治理者。不伤人要连实际施为看，不能只以出发点良善就忽略造成的损害。"]},{id:"two-nonharms-and-returning-virtue",label:"夫两不相伤，故德交归焉",showLabel:!0,sentences:[["夫两不相伤，故",{text:"德",glossary:"de"},{text:"交",glossary:"jiao"},"归焉。"]],note:["【白话】鬼神与圣人这两方面都不伤人，于是两者的德相合而归于道。此处白话依王弼对两与交归的解释。","【王弼注择要】「神不伤人，圣人亦不伤人。」注又互换句序重说，最后以「神圣合道，交归之也」解释德交归。","【读法】两在此按所据注并举鬼神与圣人，不只改写成人与鬼彼此不犯，或君民相安。交为交相、共同，归所指依注落在合道。"]}],s=[{id:"xian",term:"鲜",sense:1},{id:"li",term:"莅",sense:1},{id:"gui",term:"鬼",sense:1},{id:"shenverb",term:"神",sense:1},{id:"shen",term:"神",sense:2},{id:"shengren",term:"圣人",sense:1},{id:"jiao",term:"交",sense:1},{id:"de",term:"德",sense:5}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十章",tabindex:"-1"},[r("道德经第六十章 "),a("a",{class:"header-anchor",href:"#道德经第六十章","aria-label":'Permalink to "道德经第六十章"'},"​")],-1)),o(i,{title:"烹小鲜为何通到鬼神、圣人与两不相伤",summary:"本章先用烹小鲜比喻治理大国，再转入以道莅天下，层层说明鬼神与圣人都不伤人，最后以德交归收束。王弼始终抓住不扰、全真与神圣合道，不把治理寄托在威网显效上。",points:[{label:"先读",text:"烹小鲜先依王注不扰读，体会躁动施为如何伤害所治之物。"},{label:"再辨",text:"不神并未删去古代鬼神观念，而是接着说明其神不伤人。"},{label:"后看",text:"两不相伤依王注并举鬼神与圣人，德交归落在两者合道。"}],hint:"鲜读 xiān，为小鱼；莅读 lì，为临治。鬼与神置于古代观念中理解，神字的显神异之用与神灵称谓分开。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"治大国若烹小鲜。",tone:"从不扰起读",guide:"王弼用躁多害、静全真解释，重点在保护所治之物。"},{text:"非其神不伤人，圣人亦不伤人。",tone:"把不害落回治理者",guide:"不只求鬼神无害，也检视治理本身如何作用于人。"},{text:"夫两不相伤，故德交归焉。",tone:"依王注辨两与归",guide:"两指并举的鬼神与圣人，交归按神圣合道解释。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:s}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
